import { Column as ColumnType, Card } from "../types";
import CardItem from "./Card";
const height = window.innerHeight;

type Props = {
  column: ColumnType;
  cards: Record<string, Card>;
};

export default function Column({ column, cards }: Props) {
  return (
    <div style={{ flex: 1, height: '100%',padding: 10, borderWidth: 3, borderStyle: "solid", borderColor: "rgb(125,191,200)", borderRadius: 4, display: "flex", flexDirection: "column"  }}>
      <h3>{column.title}</h3>

      {column.cardIds.map((id) => (
        <CardItem key={id} card={cards[id]} />
      ))}
    </div>
  );
}
